<?php
require dirname(__DIR__).'/app/bootstrap.php';
require_permission('settings.manage');
ensure_v8_schema();
$pdo->exec("CREATE TABLE IF NOT EXISTS post_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id INT UNSIGNED NOT NULL, language_code VARCHAR(5) NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL, excerpt TEXT NULL, seo_title VARCHAR(220) NULL, seo_description VARCHAR(320) NULL, content LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_post_translation(post_id,language_code), UNIQUE KEY uq_translation_slug(language_code,slug), INDEX idx_translation_language_status(language_code,status), CONSTRAINT fk_translation_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$languages=['id'=>'Bahasa Indonesia','en'=>'English','es'=>'Español','fr'=>'Français','ja'=>'日本語'];
$postId=(int)($_GET['post_id']??$_POST['post_id']??0); $lang=(string)($_GET['lang']??$_POST['language_code']??'en');
if(!isset($languages[$lang])||$lang==='id')$lang='en';
$q=$pdo->prepare('SELECT id,title,slug,status FROM posts WHERE id=?');$q->execute([$postId]);$source=$q->fetch();
if(!$source){http_response_code(404);exit('Artikel sumber tidak ditemukan. Pilih artikel dari dashboard.');}
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $title=trim((string)($_POST['title']??''));$slug=slugify(trim((string)($_POST['slug']??''))?:$title);$excerpt=trim((string)($_POST['excerpt']??''));$seoTitle=trim((string)($_POST['seo_title']??''));$seoDescription=trim((string)($_POST['seo_description']??''));$content=sanitize_rich_html((string)($_POST['content']??''));$status=isset($_POST['published'])?'published':'draft';
 if($title===''||rich_html_to_text($content)==='')$errors[]='Judul dan isi terjemahan wajib diisi.';
 if(text_length($title)>220||$slug===''||text_length($slug)>240||text_length($seoTitle)>220||text_length($seoDescription)>320)$errors[]='Judul, slug, atau SEO melebihi batas panjang.';
 if(!$errors){try{$stmt=$pdo->prepare("INSERT INTO post_translations(post_id,language_code,title,slug,excerpt,seo_title,seo_description,content,status) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),slug=VALUES(slug),excerpt=VALUES(excerpt),seo_title=VALUES(seo_title),seo_description=VALUES(seo_description),content=VALUES(content),status=VALUES(status)");$stmt->execute([$postId,$lang,$title,$slug,$excerpt,$seoTitle,$seoDescription,$content,$status]);cache_clear();header('Location: '.base_url('admin/translations.php?post_id='.$postId.'&lang='.rawurlencode($lang).'&saved=1'));exit;}catch(Throwable $ex){$errors[]='Terjemahan gagal disimpan. Pastikan slug unik untuk bahasa tersebut.';error_log('NOWRD translation save failed: '.$ex->getMessage());}}
}
$tq=$pdo->prepare('SELECT * FROM post_translations WHERE post_id=? AND language_code=?');$tq->execute([$postId,$lang]);$translation=$tq->fetch()?:['title'=>'','slug'=>$source['slug'].'-'.$lang,'excerpt'=>'','seo_title'=>'','seo_description'=>'','content'=>'','status'=>'draft'];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Translations — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.trans-wrap{max-width:920px;margin:40px auto;padding:24px}.trans-form{display:grid;gap:14px}.trans-form label{display:grid;gap:6px;font-size:13px;font-weight:650}.trans-form input,.trans-form textarea,.trans-form select{font:inherit;padding:12px;border:1px solid var(--line,#ddd);border-radius:9px;width:100%;box-sizing:border-box}.trans-form textarea{min-height:110px}.trans-form .content-field{min-height:260px}.notice{padding:12px;border-radius:9px;background:#edf8df;margin:14px 0}.error{background:#fff0ed}.lang-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.lang-tabs a{padding:8px 12px;border:1px solid var(--line,#ddd);border-radius:20px}.muted{color:var(--muted,#777)}</style></head><body><main class="trans-wrap"><a href="<?=e(base_url('admin/index.php'))?>">← Dashboard</a><div class="eyebrow" style="margin-top:24px">NOWRD / PUBLISHING</div><h1>Multilingual publishing</h1><p class="muted">Terjemahan untuk artikel sumber: <strong><?=e($source['title'])?></strong> (<?=e($source['status'])?>). Bahasa Indonesia adalah konten sumber; bahasa lain disimpan terpisah.</p><div class="lang-tabs"><?php foreach($languages as $code=>$name):?><a href="<?=e(base_url('admin/translations.php?post_id='.$postId.'&lang='.$code))?>" aria-current="<?=$lang===$code?'page':'false'?>"><?=e($name)?></a><?php endforeach;?></div><?php if(isset($_GET['saved'])):?><div class="notice">Terjemahan berhasil disimpan.</div><?php endif;?><?php foreach($errors as $err):?><div class="notice error"><?=e($err)?></div><?php endforeach;?><form method="post" class="trans-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="post_id" value="<?=$postId?>"><input type="hidden" name="language_code" value="<?=e($lang)?>"><label>Bahasa tujuan<select disabled><option><?=e($languages[$lang])?> (<?=e(strtoupper($lang))?>)</option></select></label><label>Judul terjemahan<input name="title" maxlength="220" required value="<?=e($translation['title'])?>"></label><label>Slug terjemahan<input name="slug" maxlength="240" required value="<?=e($translation['slug'])?>"></label><label>Ringkasan<textarea name="excerpt"><?=e($translation['excerpt'])?></textarea></label><label>SEO title<input name="seo_title" maxlength="220" value="<?=e($translation['seo_title'])?>"></label><label>SEO description<textarea name="seo_description" maxlength="320"><?=e($translation['seo_description'])?></textarea></label><label>Konten HTML sederhana<textarea class="content-field" name="content" required><?=e($translation['content'])?></textarea></label><label style="display:flex;align-items:center;gap:9px;font-weight:500"><input style="width:auto" type="checkbox" name="published" value="1" <?=$translation['status']==='published'?'checked':''?>> Publikasikan terjemahan</label><p class="muted">Gunakan tag HTML yang aman seperti p, h2, strong, em, ul, li, blockquote, dan a. Terjemahan berstatus draft tidak tampil ke publik.</p><button class="button" type="submit">Save translation</button></form></main></body></html>
